const listStalePendingMatch = `-- name: ListStalePendingMatch :many
SELECT id
FROM payments_ext.transfers
WHERE status = 'pending_match' AND updated_at < $1
ORDER BY created_at
LIMIT $2
`

type ListStalePendingMatchParams struct {
	Cutoff  time.Time
	MaxRows int32
}

// The rescue sweep: pending_match transfers whose last activity is older
// than the cutoff — their match job died somewhere; re-enqueue.
func (q *Queries) ListStalePendingMatch(ctx context.Context, arg ListStalePendingMatchParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listStalePendingMatch, arg.Cutoff, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

